// primitive_element.go — the primitive element theorem: a finite
// separable extension of an infinite field is generated by one element.

package algebraic_closure

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/algebraic_element"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field_automorphism"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field_extension"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/galois_correspondence"
	"github.com/euc-ai/xugo/library/proofs/algebra/group/symmetric_group"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/comm_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/integral_domain"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_homomorphism"
	"github.com/euc-ai/xugo/library/proofs/nat_num/nat_order"
	"github.com/euc-ai/xugo/library/proofs/sets/finite_set"
	"github.com/euc-ai/xugo/library/proofs/sets/functions"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_image"
	"github.com/euc-ai/xugo/library/registry"
)

// PrimitiveElement — a finite separable extension K of an infinite field B
// is simple: K = B(z) for some z ∈ K. Inside an algebraic closure of L, two
// elements a, b of K lie in the root field of their minimal polynomials, a
// finite Galois extension of B, where all but finitely many r ∈ B make
// a + r·b generate both; pulled back to L, any two elements of K share a
// primitive element in K, and an element of K of largest degree over B
// then generates K.
var PrimitiveElement = primitiveElementThm{family.Add(registry.ProofEntry{
	Name: "PrimitiveElement",
	Key:  "prop_f6967267aacbe17a",
	Build: family.Sections(Statement{
		Binders: "∀L:field_on(A). ∀B K:set(A).",
		Hypotheses: []string{
			"subfield(L, B)",
			"subfield(L, K)",
			"B ⊆ K",
			"infinite(B)",
			"finite_extension(L, B, K)",
			"∀x:A. x ∈ K ⇒ separable_over(L, B, x)",
		},
		Conclusion: "∃z:A. z ∈ K ∧ field_adjoin(L, B, {z}) = K",
	}, func(ctx *Script, headline string) *GoalStackNode {
		// If any two elements of a finite extension K/B lie in one simple
		// extension inside K, an element u of largest degree [B(u) : B]
		// generates K: every v ∈ K lies with u in some B(c) ⊆ K, and B(u) ⊆ B(c)
		// with [B(c) : B] ≤ [B(u) : B] forces B(u) = B(c) ∋ v.
		primitiveFromPairs := ctx.Lemma(Statement{
			Binders: "∀L:field_on(A). ∀B K:set(A).",
			Hypotheses: []string{
				"subfield(L, B)",
				"subfield(L, K)",
				"B ⊆ K",
				"finite_extension(L, B, K)",
				"∀a b:A. a ∈ K ∧ b ∈ K ⇒ ∃c:A. c ∈ K ∧ a ∈ field_adjoin(L, B, {c}) ∧ b ∈ field_adjoin(L, B, {c})",
			},
			Conclusion: "∃a:A. a ∈ K ∧ field_adjoin(L, B, {a}) = K",
		}, func(
			a *Argument,
			L field.FieldFact[on.L],
			B, K *Expr[Set[A]],
			BField, KField, BInK, finite, pairs Fact,
		) {
			l := a.TermAs[FieldOps[A]]("L")
			_, dDef := a.LetAs[Fun[A, Nat]]("d", "λx:A. extension_degree(L, B, field_adjoin(L, B, {x}))")
			_, DDef := a.LetAs[Set[Nat]]("D", "image(d, K)")
			simple := a.Have(
				"each x ∈ K generates a subfield B(x) ⊆ K, finite over B of degree at most [K : B]",
				Statement{
					Binders:    "∀x:A.",
					Hypotheses: []string{"x ∈ K"},
					Conclusion: "subfield(L, field_adjoin(L, B, {x})) ∧ " +
						"B ⊆ field_adjoin(L, B, {x}) ∧ " +
						"x ∈ field_adjoin(L, B, {x}) ∧ " +
						"field_adjoin(L, B, {x}) ⊆ K ∧ " +
						"finite_extension(L, B, field_adjoin(L, B, {x})) ∧ " +
						"d(x) ≤ extension_degree(L, B, K)",
				},
				Derive(func(b *Argument) {
					x := b.FixAs[A]("x")
					xInK := b.Assume()
					E, EDef := b.LetAs[Set[A]]("E", "field_adjoin(L, B, {x})")
					between := b.Have(
						"B(x) is a subfield between B and K containing x",
						"subfield(L, E) ∧ B ⊆ E ∧ x ∈ E ∧ E ⊆ K",
						Simp(Fwd(EDef)),
						By(BField, KField, BInK, xInK, algebraic_element.AdjoinElementBetween.Read(L).At(B, K, x)))
					degree := b.Have(
						"d(x) is the degree of B(x) over B",
						"d(x) = extension_degree(L, B, E)",
						Simp(Fwd(dDef), Fwd(EDef)),
						Basic())
					bound := b.Have(
						"B(x) is finite over B of degree at most [K : B]",
						"finite_extension(L, B, E) ∧ extension_degree(L, B, E) ≤ extension_degree(L, B, K)",
						By(BField, KField, finite, between, field_extension.IntermediateDegree.Read(L).At(B, E, K)))
					b.Show(
						"collect the properties of B(x)",
						By(Normalized, between, degree, bound))
				}))
			bounded := a.Have(
				"the degrees in D are bounded by [K : B]",
				"∀n:num. n ∈ D ⇒ n ≤ extension_degree(L, B, K)",
				BySets(DDef, simple))
			inhabited := a.Have(
				"D is not empty",
				"∃n:num. n ∈ D",
				Witness(a.TermAs[Nat]("d(L.zero)")),
				BySets(DDef, KField, field.SubfieldZero.At(l, K)))
			bound := a.Have(
				"D has an upper bound",
				"∃N:num. ∀n:num. n ∈ D ⇒ n ≤ N",
				Witness(a.TermAs[Nat]("extension_degree(L, B, K)")),
				By(bounded))
			_, maximum := a.ObtainAs[Nat](
				"so D has a largest element m",
				"∃m:num. m ∈ D ∧ (∀n:num. n ∈ D ⇒ n ≤ m)",
				By(bound, inhabited, nat_order.MaximumExists.At(a.TermAs[Fun[Nat, Bool]]("λn:num. n ∈ D"))))
			u, attains := a.ObtainAs[A](
				"attained at some u ∈ K",
				"∃u:A. u ∈ K ∧ d(u) = m",
				BySets(DDef, maximum))
			U, UDef := a.LetAs[Set[A]]("U", "field_adjoin(L, B, {u})")
			uField := a.Have(
				"U = B(u) is a subfield over B inside K, finite over B",
				"subfield(L, U) ∧ B ⊆ U ∧ u ∈ U ∧ U ⊆ K ∧ finite_extension(L, B, U)",
				By(Normalized, simple.At(u), UDef, attains))
			maximal := a.Have(
				"u has the largest degree",
				"∀x:A. x ∈ K ⇒ d(x) ≤ d(u)",
				BySets(DDef, maximum, attains))
			covers := a.Have(
				"every element of K lies in U",
				"∀v:A. v ∈ K ⇒ v ∈ U",
				Derive(func(b *Argument) {
					v := b.FixAs[A]("v")
					vInK := b.Assume()
					c, common := b.ObtainAs[A](
						"u and v lie in one simple extension B(c) with c ∈ K",
						"∃c:A. c ∈ K ∧ u ∈ field_adjoin(L, B, {c}) ∧ v ∈ field_adjoin(L, B, {c})",
						By(pairs.At(u, v), attains, vInK))
					C, CDef := b.LetAs[Set[A]]("C", "field_adjoin(L, B, {c})")
					cField := b.Have(
						"C = B(c) is a subfield over B inside K, finite over B",
						"subfield(L, C) ∧ B ⊆ C ∧ C ⊆ K ∧ finite_extension(L, B, C)",
						By(Normalized, simple.At(c), CDef, common))
					uSingleton := b.Have(
						"u lies in C",
						"{u} ⊆ C",
						BySets(common))
					UInC := b.Have(
						"so U ⊆ C",
						"U ⊆ C",
						BySets(
							UDef,
							cField,
							uSingleton,
							algebraic_element.AdjoinLeast.Read(L).At(B, b.TermAs[Set[A]]("{u}"), C)))
					comparison := b.Have(
						"U is an intermediate field of C over B",
						"extension_degree(L, B, U) ≤ extension_degree(L, B, C) ∧ "+
							"(extension_degree(L, B, U) = extension_degree(L, B, C) ⇒ U = C)",
						By(BField, uField, cField, UInC, field_extension.IntermediateDegree.Read(L).At(B, U, C)))
					parts := b.Conjuncts(
						comparison,
						"[U : B] ≤ [C : B]",
						"equal degrees force U = C")
					reverse := b.Have(
						"[C : B] ≤ [U : B] by the maximality of u",
						"extension_degree(L, B, C) ≤ extension_degree(L, B, U)",
						By(maximal.At(c), dDef, CDef, UDef, common))
					equalDegree := b.Have(
						"so the degrees agree",
						"extension_degree(L, B, U) = extension_degree(L, B, C)",
						ByArith(parts[0], reverse))
					equal := b.Have(
						"hence U = C",
						"U = C",
						By(equalDegree, parts[1]))
					b.Show(
						"so v ∈ C = U",
						BySets(equal, common))
				}))
			generates := a.Have(
				"U = K",
				"U = K",
				BySets(covers, uField))
			a.Take(u)
			a.Show(
				"u generates K",
				Simp(Rev(UDef)),
				By(generates, attains))
		})

		// In a finite Galois extension N of an infinite field B, two elements
		// a, b of N lie in B(a + r·b) for all but finitely many r ∈ B: an
		// automorphism fixing a + r·b but moving b would force
		// r = (a - σ(a)) / (σ(b) - b), one of finitely many values.
		galoisPairPrimitive := ctx.Lemma(Statement{
			Binders: "∀L:field_on(A). ∀B N:set(A). ∀a b:A.",
			Hypotheses: []string{
				"subfield(L, B)",
				"subfield(L, N)",
				"B ⊆ N",
				"galois_over(L, B, N)",
				"infinite(B)",
				"a ∈ N",
				"b ∈ N",
			},
			Conclusion: "∃r:A. " +
				"    r ∈ B ∧ a ∈ field_adjoin(L, B, {a + r * b}) ∧ b ∈ field_adjoin(L, B, {a + r * b})",
		}, func(
			arg *Argument,
			L field.FieldFact[on.L],
			B, N *Expr[Set[A]],
			a, b *Expr[A],
			BField, NField, BInN, galois, infiniteB, aInN, bInN Fact,
		) {
			l := arg.TermAs[FieldOps[A]]("L")
			H, HDef := arg.LetAs[Set[symmetric_group.Permutation[A]]]("H", "field_automorphisms(L, B, N)")
			T, TDef := arg.LetAs[Set[A]](
				"T", "image(λσ:permutation(A). (a - permutation_map(σ, a)) / (permutation_map(σ, b) - b), H)")
			finiteH := arg.Have(
				"the Galois group H of N over B is finite",
				"finite(H)",
				By(
					Normalized,
					HDef,
					BField,
					NField,
					BInN,
					galois,
					galois_correspondence.GaloisOverDef.At(l, B, N),
					field_automorphism.AutomorphismsBound.Read(L).At(B, N)))
			finiteT := arg.Have(
				"so the set T of bad ratios is finite",
				"finite(T)",
				By(
					Normalized,
					finiteH,
					TDef,
					finite_set.FiniteImage.At(
						arg.TermAs[Fun[symmetric_group.Permutation[A], A]](
							"λσ:permutation(A). (a - permutation_map(σ, a)) / (permutation_map(σ, b) - b)"),
						H)))
			r, avoids := arg.ObtainAs[A](
				"B is infinite, so some r ∈ B avoids T",
				"∃r:A. r ∈ B ∧ r ∉ T",
				BySets(finiteT, infiniteB, finite_set.InfiniteDef.At(B), finite_set.FiniteSubset.At(B, T)))
			c, cDef := arg.LetAs[A]("c", "a + r * b")
			D, DDef := arg.LetAs[Set[A]]("D", "field_adjoin(L, B, {c})")
			members := arg.Have(
				"r, a, b and c = a + r·b lie in N and in L",
				"r ∈ N ∧ a ∈ L.carrier ∧ b ∈ L.carrier ∧ r ∈ L.carrier ∧ c ∈ N ∧ c ∈ L.carrier",
				BySets(
					cDef,
					avoids,
					BInN,
					aInN,
					bInN,
					NField,
					field.SubfieldSubset.At(l, N),
					field.SubfieldMul.At(l, N, r, b),
					field.SubfieldAdd.At(l, N, a, arg.TermAs[A]("r * b"))))
			DField := arg.Have(
				"D = B(c) is a subfield between B and N containing c",
				"subfield(L, D) ∧ B ⊆ D ∧ c ∈ D ∧ D ⊆ N",
				Simp(Fwd(DDef)),
				By(members, BField, NField, BInN, algebraic_element.AdjoinElementBetween.Read(L).At(B, N, c)))
			fixed := arg.Have(
				"every automorphism fixing D fixes a and b",
				Statement{
					Binders:    "∀σ:permutation(A).",
					Hypotheses: []string{"σ ∈ field_automorphisms(L, D, N)"},
					Conclusion: "permutation_map(σ, a) = a ∧ permutation_map(σ, b) = b",
				},
				Derive(func(d *Argument) {
					σ := d.FixAs[symmetric_group.Permutation[A]]("σ")
					fixesD := d.Assume()
					inH := d.Have(
						"σ lies in H and moves a and b within N",
						"σ ∈ H ∧ permutation_map(σ, a) ∈ N ∧ permutation_map(σ, b) ∈ N",
						BySets(
							HDef,
							fixesD,
							DField,
							aInN,
							bInN,
							field_automorphism.AutomorphismsAntitone.Read(L).At(B, D, N),
							field_automorphism.FieldAutomorphismsDef.At(l, D, N),
							symmetric_group.SymmetricGroupMapsInto.At(N, σ, a),
							symmetric_group.SymmetricGroupMapsInto.At(N, σ, b)))
					fixesC := d.Have(
						"σ fixes c = a + r·b, as c ∈ D and r ∈ B ⊆ D",
						"permutation_map(σ, a) + r * permutation_map(σ, b) = a + r * b",
						BySets(
							cDef,
							d.Unfolded(fixesD, field_automorphism.FieldAutomorphismsDef),
							avoids,
							DField,
							NField,
							aInN,
							bInN,
							field.SubfieldMul.At(l, N, r, b)))
					images := d.Have(
						"σ(a) and σ(b) lie in L",
						"permutation_map(σ, a) ∈ L.carrier ∧ permutation_map(σ, b) ∈ L.carrier",
						BySets(inH, NField, field.SubfieldSubset.At(l, N)))
					fixesB := d.Have(
						"σ fixes b",
						"permutation_map(σ, b) = b",
						Derive(func(e *Argument) {
							moved := e.SupposeNot()
							u, uDef := e.LetAs[A]("u", "permutation_map(σ, b) - b")
							v, vDef := e.LetAs[A]("v", "a - permutation_map(σ, a)")
							nonzero := e.Have(
								"u = σ(b) - b is a nonzero point of L, and v = a - σ(a) a point of L",
								"u ∈ L.carrier ∧ v ∈ L.carrier ∧ u ≠ L.zero",
								uDef.Rw(),
								vDef.Rw(),
								ByArith(
									moved,
									images,
									members,
									comm_ring.SubIn.Read(field.RingOn.Read(L)).AsFact().At(e.TermAs[A]("permutation_map(σ, b)"), b),
									comm_ring.SubIn.Read(field.RingOn.Read(L)).AsFact().At(a, e.TermAs[A]("permutation_map(σ, a)"))))
							scaled := e.Have(
								"σ fixing c gives u·r = v",
								"u * r = v",
								uDef.Rw(),
								vDef.Rw(),
								ByArith(L, fixesC, images, members))
							ratio := e.Have(
								"so r = v / u",
								"r = v / u",
								By(
									Normalized,
									scaled,
									nonzero,
									members,
									field.DivIn.Read(L).AsFact().At(v, u),
									field.DivLeftMulOn.Read(L).AsFact().At(v, u),
									integral_domain.MulCancelLeft.Read(integral_domain.FieldIntegralDomain.Read(L)).AsFact().At(
										u, r, e.TermAs[A]("v / u"))))
							e.Show(
								"then r would be one of the bad ratios in T",
								BySets(ratio, uDef, vDef, TDef, avoids, inH))
						}))
					d.Show(
						"and then σ fixes a as well",
						ByArith(L, fixesB, fixesC, images, members))
				}))
			fixedField := arg.Have(
				"by the Galois correspondence the automorphisms fixing D fix exactly D",
				"fixed_field(N, field_automorphisms(L, D, N)) = D",
				By(
					DField,
					BField,
					NField,
					BInN,
					galois,
					galois_correspondence.CorrespondenceFixed.Read(L).At(B, D, N)))
			inD := arg.Have(
				"so a and b lie in D",
				"a ∈ D ∧ b ∈ D",
				BySets(
					fixed,
					fixedField,
					aInN,
					bInN,
					field_automorphism.FixedFieldDef.At(
						N, arg.TermAs[Set[symmetric_group.Permutation[A]]]("field_automorphisms(L, D, N)"))))
			arg.Take(r)
			arg.Show(
				"r has the required property",
				Simp(Rev(cDef)),
				Simp(Rev(DDef)),
				By(inD, avoids))
		})

		// In an algebraically closed field, two separable elements a, b over
		// an infinite subfield B share a primitive element a + r·b: they lie in
		// the root field of their minimal polynomials, which is finite Galois
		// over B.
		closedPairPrimitive := ctx.Lemma(Statement{
			Binders: "∀L:field_on(A). ∀B:set(A). ∀a b:A.",
			Hypotheses: []string{
				"algebraically_closed_field(L)",
				"subfield(L, B)",
				"infinite(B)",
				"a ∈ L.carrier",
				"b ∈ L.carrier",
				"separable_over(L, B, a)",
				"separable_over(L, B, b)",
			},
			Conclusion: "∃r:A. " +
				"    r ∈ B ∧ a ∈ field_adjoin(L, B, {a + r * b}) ∧ b ∈ field_adjoin(L, B, {a + r * b})",
		}, func(
			arg *Argument,
			L field.FieldFact[on.L],
			B *Expr[Set[A]],
			a, b *Expr[A],
			closed, BField, infiniteB, aInL, bInL, aSeparable, bSeparable Fact,
		) {
			l := arg.TermAs[FieldOps[A]]("L")
			p, pDef := arg.LetAs[Fun[Nat, A]]("p", "minimal_polynomial(L, B, a)")
			q, qDef := arg.LetAs[Fun[Nat, A]]("q", "minimal_polynomial(L, B, b)")
			P, PDef := arg.LetAs[Set[Fun[Nat, A]]]("P", "{p, q}")
			R, RDef := arg.LetAs[Set[A]](
				"R", "{x:A | x ∈ L.carrier ∧ (∃f:(num → A). f ∈ P ∧ polynomial_eval(f, x) = L.zero)}")
			N, NDef := arg.LetAs[Set[A]]("N", "field_adjoin(L, B, R)")
			am, bm := arg.MemberOf[on.L](a, aInL), arg.MemberOf[on.L](b, bInL)
			algebraic := arg.Have(
				"a and b are algebraic over B",
				"algebraic_over(L, B, a) ∧ algebraic_over(L, B, b)",
				By(
					aSeparable,
					bSeparable,
					galois_correspondence.SeparableOverDef.At(l, B, a),
					galois_correspondence.SeparableOverDef.At(l, B, b)))
			minimal := arg.Have(
				"p and q are nonconstant separable polynomials over B with roots a and b",
				"polynomial_over(B, p) ∧ "+
					"0 < polynomial_degree(p) ∧ "+
					"polynomial_separable(restrict_ring(field_ring(L), B), p) ∧ "+
					"polynomial_eval(p, a) = L.zero ∧ "+
					"polynomial_over(B, q) ∧ "+
					"0 < polynomial_degree(q) ∧ "+
					"polynomial_separable(restrict_ring(field_ring(L), B), q) ∧ "+
					"polynomial_eval(q, b) = L.zero",
				By(
					pDef,
					qDef,
					BField,
					aSeparable,
					bSeparable,
					algebraic,
					algebraic_element.MinimalPolynomialSpec.Read(L).At(B, am),
					algebraic_element.MinimalPolynomialPositive.Read(L).At(B, am),
					galois_correspondence.SeparableOverDef.At(l, B, a),
					algebraic_element.MinimalPolynomialSpec.Read(L).At(B, bm),
					algebraic_element.MinimalPolynomialPositive.Read(L).At(B, bm),
					galois_correspondence.SeparableOverDef.At(l, B, b)))
			finiteP := arg.Have(
				"the family P = {p, q} is finite",
				"finite(P)",
				PDef.Rw(),
				By(finite_set.FiniteInsert.At(p, arg.TermAs[Set[Fun[Nat, A]]]("{q}")), finite_set.FiniteSing.At(q)))
			nonconstantSeparable := arg.Have(
				"every member of P is a nonconstant separable polynomial over B",
				Statement{
					Binders:    "∀f:(num → A).",
					Hypotheses: []string{"f ∈ P"},
					Conclusion: "polynomial_over(B, f) ∧ " +
						"0 < polynomial_degree(f) ∧ " +
						"polynomial_separable(restrict_ring(field_ring(L), B), f)",
				},
				Derive(func(c *Argument) {
					c.FixAs[Fun[Nat, A]]("f")
					member := c.Assume()
					c.Cases(c.TermAs[Bool]("f = p"))
					c.When(
						"f is the minimal polynomial of a",
						func(d *Argument, isP Fact) {
							d.Show(
								"p has these properties",
								isP.Rw(),
								By(minimal))
						})
					c.Otherwise(
						"f is the minimal polynomial of b",
						func(d *Argument, notP Fact) {
							isQ := d.Have(
								"f is q",
								"f = q",
								BySets(notP, member, PDef))
							d.Show(
								"q has these properties",
								isQ.Rw(),
								By(minimal))
						})
				}))
			roots := arg.Have(
				"the roots R of p and q lie in L and include a and b",
				"R ⊆ L.carrier ∧ a ∈ R ∧ b ∈ R",
				BySets(RDef, PDef, aInL, bInL, minimal))
			rootField := arg.Have(
				"N = B(R) is a subfield over B containing a and b",
				"subfield(L, N) ∧ B ⊆ N ∧ a ∈ N ∧ b ∈ N",
				BySets(
					NDef,
					roots,
					BField,
					field.SubfieldSubset.At(l, B),
					algebraic_element.AdjoinSubfield.Read(L).At(B, R)))
			galois := arg.Have(
				"N is Galois over B",
				"galois_over(L, B, N)",
				NDef.Rw(),
				RDef.Rw(),
				By(
					finiteP,
					nonconstantSeparable,
					closed,
					BField,
					ClosedFieldSplits.Read(L),
					galois_correspondence.SeparableRootFieldGalois.Read(L).At(B, P)))
			arg.Show(
				"apply the Galois pair argument in N",
				By(L, rootField, BField, infiniteB, galois, At(galoisPairPrimitive, l, B, N, a, b)))
		})

		// An isomorphism of F onto a subfield of G is a ring homomorphism of F
		// into G.
		embeddingHomomorphism := ctx.Lemma(Statement{
			Binders: "∀F:field_on(A). ∀G:field_on(B). ∀f:(A → B).",
			Hypotheses: []string{
				"subfield(G, image(f, F.carrier))",
				"ring_isomorphism(field_ring(F), restrict_ring(field_ring(G), image(f, F.carrier)), f)",
			},
			Conclusion: "ring_homomorphism(field_ring(F), field_ring(G), f)",
		}, func(
			a *Argument,
			F field.FieldFact[on.F],
			G field.FieldFact[on.G],
			f *Arrow[A, B],
			imageField, isomorphism Fact,
		) {
			fRing := a.TermAs[comm_ring.RingOps[A]]("field_ring(F)")
			imageRing := a.TermAs[comm_ring.RingOps[B]]("restrict_ring(field_ring(G), image(f, F.carrier))")
			intoImage := a.Have(
				"the isomorphism is a homomorphism onto the image field",
				"ring_homomorphism(field_ring(F), restrict_ring(field_ring(G), image(f, F.carrier)), f)",
				By(isomorphism, ring_homomorphism.RingIsomorphismDef.At(fRing, imageRing, f)))
			image := a.TermAs[Set[B]]("image(f, F.carrier)")
			a.Show(
				"the image field lies in the ambient target field",
				By(
					imageField,
					intoImage,
					field.RingOn.Read(G),
					field.SubfieldSubset.At(a.TermAs[FieldOps[B]]("G"), image),
					ring_homomorphism.RingHomExtendTarget.At(
						fRing, a.TermAs[comm_ring.RingOps[B]]("field_ring(G)"), f, image)))
		})

		// An injective map identifies an element of U with a point of E ⊆ U
		// when their images agree.
		injectivePreimage := ctx.Lemma(Statement{
			Binders: "∀f:(A → B). ∀U E:set(A). ∀x:A.",
			Hypotheses: []string{
				"injective_on(U, f)",
				"E ⊆ U",
				"x ∈ U",
				"f(x) ∈ image(f, E)",
			},
			Conclusion: "x ∈ E",
		}, func(
			a *Argument,
			f *Arrow[A, B],
			U, E *Expr[Set[A]],
			x *Expr[A],
			injective, EInU, xInU, imageMember Fact,
		) {
			a.Show(
				"a preimage of f(x) in E is x itself",
				BySets(injective, EInU, xInU, imageMember, functions.InjectiveOnDef.At(U, f)))
		})

		return ctx.Theorem(headline, func(
			arg *Argument,
			L field.FieldFact[on.L],
			B, K *Expr[Set[A]],
			BField, KField, BInK, infiniteB, finite, separable Fact,
		) {
			l := arg.TermAs[FieldOps[A]]("L")
			lCarrier := arg.TermAs[Set[A]]("L.carrier")
			pairs := arg.Have(
				"any two elements of K lie in one simple extension of B inside K",
				"∀a b:A. a ∈ K ∧ b ∈ K ⇒ ∃c:A. c ∈ K ∧ a ∈ field_adjoin(L, B, {c}) ∧ b ∈ field_adjoin(L, B, {c})",
				Derive(func(d *Argument) {
					a := d.FixAs[A]("a")
					b := d.FixAs[A]("b")
					inK := d.Assume()
					f, fDef := d.LetAs[Fun[A, _ClosureHost]]("f", "«closureEmbedding»")
					members := d.Have(
						"a and b lie in L and are separable over B",
						"a ∈ L.carrier ∧ b ∈ L.carrier ∧ separable_over(L, B, a) ∧ separable_over(L, B, b)",
						BySets(inK, KField, separable, field.SubfieldSubset.At(l, K)))
					Ω, closure := d.UnpackAs[FieldOps[_ClosureHost]](
						d.Simplified(AlgebraicClosureFieldOn.Read(L), Rev(fDef)), "Ω")
					closed := d.Conjuncts(
						closure,
						"Ω is a field",
						"Ω is algebraically closed",
						"f carries L onto a subfield of Ω",
						"f is an isomorphism of L onto that subfield",
						"Ω is algebraic over the image of L")
					hom := d.Have(
						"f is a ring homomorphism from L into Ω",
						"ring_homomorphism(field_ring(L), field_ring(Ω), f)",
						By(L, closed[0], closed[2], closed[3], At(embeddingHomomorphism, l, Ω, f)))
					injective := d.Have(
						"f is one-to-one on L, as every homomorphism of fields is",
						"injective_on(L.carrier, f)",
						By(closed[0], hom, ring_homomorphism.FieldHomomorphismInjective.Read(L).At(Ω, f)))
					baseImage := d.Have(
						"f carries B onto a subfield of Ω",
						"subfield(Ω, image(f, B)) ∧ B ⊆ L.carrier",
						By(
							closed[0],
							hom,
							BField,
							algebraic_element.FieldEmbeddingSubfieldsAdjoin.Read(L).At(Ω, f),
							field.SubfieldSubset.At(l, B)))
					infiniteImage := d.Have(
						"the image of B in Ω is infinite",
						"injective_on(B, f) ∧ infinite(image(f, B))",
						By(
							infiniteB,
							injective,
							baseImage,
							functions.InjectiveOnSubset.At(f, B, lCarrier),
							finite_set.InfiniteImage.At(f, B)))
					images := d.Have(
						"f(a) and f(b) lie in Ω and are separable over the image of B",
						"f(a) ∈ Ω.carrier ∧ "+
							"f(b) ∈ Ω.carrier ∧ "+
							"separable_over(Ω, image(f, B), f(a)) ∧ "+
							"separable_over(Ω, image(f, B), f(b))",
						By(
							L,
							closed[0],
							closed[2],
							BField,
							members,
							hom,
							field.SubfieldSubset.At(Ω, d.TermAs[Set[_ClosureHost]]("image(f, L.carrier)")),
							set_image.ImageSubsetIff.At(f, lCarrier, d.TermAs[Set[_ClosureHost]]("Ω.carrier")),
							galois_correspondence.FieldEmbeddingSeparable.At(l, Ω, f, B, a),
							galois_correspondence.FieldEmbeddingSeparable.At(l, Ω, f, B, b)))
					_, combination := d.ObtainAs[_ClosureHost](
						"in Ω some r in the image of B makes f(a) + r·f(b) generate f(a) and f(b)",
						"∃r:set(prod(num, num → A)). "+
							"    r ∈ image(f, B) ∧ "+
							"    f(a) ∈ field_adjoin(Ω, image(f, B), {f(a) + r * f(b)}) ∧ "+
							"    f(b) ∈ field_adjoin(Ω, image(f, B), {f(a) + r * f(b)})",
						By(
							closed[1],
							closed[0],
							infiniteImage,
							baseImage,
							images,
							At(
								closedPairPrimitive,
								Ω,
								d.TermAs[Set[_ClosureHost]]("image(f, B)"),
								d.TermAs[_ClosureHost]("f(a)"),
								d.TermAs[_ClosureHost]("f(b)"))))
					generators := d.Conjuncts(
						combination,
						"r lies in the image of B",
						"f(a) lies in the field generated by f(a) + r·f(b)",
						"f(b) lies in the field generated by f(a) + r·f(b)")
					x, preimage := d.UnpackAs[A](d.Simplified(generators[0], Fwd(set_basic.InImage)), "x")
					pulledBack := d.Conjuncts(
						preimage,
						"r = f(x)",
						"x lies in B")
					u, uDef := d.LetAs[A]("u", "a + x * b")
					E, EDef := d.LetAs[Set[A]]("E", "field_adjoin(L, B, {u})")
					xIn := d.Have(
						"x lies in B ⊆ K, so in K and in L",
						"x ∈ K ∧ x ∈ L.carrier",
						BySets(BInK, pulledBack[1], KField, field.SubfieldSubset.At(l, K)))
					uIn := d.Have(
						"u = a + x·b lies in K and in L",
						"u ∈ K ∧ u ∈ L.carrier",
						BySets(
							uDef,
							xIn,
							inK,
							KField,
							field.SubfieldSubset.At(l, K),
							field.SubfieldMul.At(l, K, x, b),
							field.SubfieldAdd.At(l, K, a, d.TermAs[A]("x * b"))))
					uImage := d.Have(
						"f carries u to f(a) + r·f(b)",
						"f(u) = f(a) + r * f(b)",
						pulledBack[0].Rw(),
						uDef.Rw(),
						By(
							members,
							xIn,
							comm_ring.MulIn.Read(field.RingOn.Read(L)).AsFact().At(x, b),
							ring_homomorphism.MapAdd.Read(hom).AsFact().At(a, d.TermAs[A]("x * b")),
							ring_homomorphism.MapMul.Read(hom).AsFact().At(x, b)))
					EField := d.Have(
						"E = B(u) is a subfield of L",
						"subfield(L, E) ∧ E ⊆ L.carrier ∧ {u} ⊆ L.carrier",
						BySets(
							EDef,
							BField,
							uIn,
							algebraic_element.AdjoinElementSubfield.Read(L).AsFact().At(B, u),
							field.SubfieldSubset.At(l, E)))
					singleton := d.Have(
						"f carries {u} to {f(u)}",
						"image(f, {u}) = {f(u)}",
						BySets())
					imageE := d.Have(
						"f carries E onto the image of B with f(u) adjoined",
						"image(f, E) = field_adjoin(Ω, image(f, B), {f(u)})",
						By(
							Normalized,
							L,
							closed[0],
							EDef,
							singleton,
							hom,
							baseImage,
							EField,
							algebraic_element.FieldEmbeddingSubfieldsAdjoin.Read(L).At(Ω, f)))
					inImageE := d.Have(
						"so f(a) and f(b) lie in the image of E",
						"f(a) ∈ image(f, E) ∧ f(b) ∈ image(f, E)",
						By(imageE, uImage, generators[1], generators[2]))
					inE := d.Have(
						"f being one-to-one, a and b lie in E",
						"a ∈ E ∧ b ∈ E",
						By(
							inImageE,
							injective,
							EField,
							members,
							At(injectivePreimage, f, lCarrier, E, a),
							At(injectivePreimage, f, lCarrier, E, b)))
					d.Take(u)
					d.Show(
						"u ∈ K generates a field over B containing a and b",
						Simp(Rev(EDef)),
						By(inE, uIn))
				}))
			arg.Show(
				"an element of K of largest degree over B generates K",
				By(L, BField, KField, BInK, finite, pairs, At(primitiveFromPairs, l, B, K)))
		})
	}),
})}
